import Foundation

/// User-visible strings (FE-204), keyed by English text so a key with no translation shows English.
/// Base tables: `Resources/en.lproj/Localizable.strings` and `.stringsdict`, regenerated by `scripts/extract-strings.sh`.
/// A language is a `Resources/<language>.lproj`; `Bundle` picks it from the user's preferred languages.
public enum L10n {
    /// Bundle holding `Localizable.strings` (the app bundle).
    public static var bundle: Bundle = .main {
        didSet { templates.removeAllObjects() }
    }

    /// The language the interface is actually showing, which decides its direction.
    public static var language: String { bundle.preferredLocalizations.first ?? StringTableCheck.baseLanguage }

    /// Fixed for the run: the app shows one language from launch to quit.
    public static let isRightToLeft = Locale.Language(identifier: language).characterDirection == .rightToLeft

    public static func tr(_ key: String) -> String { tr(key, in: bundle) }

    static func tr(_ key: String, in bundle: Bundle) -> String {
        guard !key.isEmpty else { return key }
        return bundle.localizedString(forKey: key, value: key, table: nil)
    }

    private static let missing = "\u{1}missing"

    /// Whether the string table has an entry for `key` (scripted checks and the string-table test).
    public static func hasEntry(_ key: String) -> Bool {
        bundle.localizedString(forKey: key, value: missing, table: nil) != missing
    }

    /// A localized format string filled with arguments (`%@`, `%d`, `%1$@`…). Text arguments are direction-isolated,
    /// so this result is for showing only: text that becomes a file name comes from `plainFormat`.
    public static func format(_ key: String, _ arguments: CVarArg...) -> String {
        String(format: template(key), locale: Locale.current, arguments: arguments.map(isolated))
    }

    /// As `format`, for text that becomes a file name. No locale: localized formatting adds its own direction marks.
    /// A translation holding a path separator would turn the name into a path, so it falls back to English.
    public static func plainFormat(_ key: String, _ arguments: CVarArg...) -> String { plainFormat(key, arguments, in: bundle) }

    static func plainFormat(_ key: String, _ arguments: [CVarArg], in bundle: Bundle) -> String {
        let translated = template(key, in: bundle)
        return String(format: translated.contains("/") || translated.contains("\0") ? key : translated, arguments: arguments)
    }

    /// A counted sentence in the language's plural form. `count` is the first argument (`%lld`, or `%1$lld` when the
    /// sentence reorders); `one` and `other` are the English forms, and `other` is the key in `Localizable.stringsdict`.
    /// Static strings, so every form is a literal the extraction script can see.
    public static func plural(one: StaticString, other: StaticString, _ count: Int, _ arguments: CVarArg...) -> String {
        plural(one: one.description, other: other.description, count, arguments, in: bundle, usable: usablePluralKeys, locale: pluralLocale)
    }

    static func plural(one: String, other: String, _ count: Int, _ arguments: [CVarArg], in bundle: Bundle, usable: Set<String>, locale: Locale) -> String {
        let translated = usable.contains(other) ? bundle.localizedString(forKey: other, value: missing, table: nil) : missing
        // Only the checked plural rule may come back; any other text would reach String(format:) unchecked.
        let template = translated == PluralTable.ruleFormat ? translated : (count == 1 ? one : other)
        return String(format: template, locale: locale, arguments: [Int64(count)] + arguments.map(isolated))
    }

    private static let usablePluralKeys = PluralTable.usableKeys(in: bundle, language: language)
    private static let pluralLocale = pluralLocale(language: language, current: .current)

    /// Foundation takes the plural rule from the format's locale, so a language chosen apart from the region
    /// needs a locale that speaks it while keeping the user's region and digits.
    static func pluralLocale(language: String, current: Locale) -> Locale {
        guard let shown = Locale.Language(identifier: language).languageCode, shown != current.language.languageCode else { return current }
        var components = Locale.Components(locale: current)
        components.languageComponents = Locale.Language.Components(languageCode: shown, region: current.region)
        components.numberingSystem = current.numberingSystem
        return Locale(components: components)
    }

    /// The translated format string. A table with the wrong specifiers can't get past the build,
    /// but one edited afterwards must still never reach `String(format:)`, so it falls back to English.
    public static func template(_ key: String) -> String {
        if let cached = templates.object(forKey: key as NSString) { return cached as String }
        let checked = template(key, in: bundle)
        templates.setObject(checked as NSString, forKey: key as NSString)
        return checked
    }

    /// Checked templates by key: Details formats a size or date with them on every visible row.
    private static let templates = NSCache<NSString, NSString>()

    static func template(_ key: String, in bundle: Bundle) -> String {
        let translated = tr(key, in: bundle)
        return translated == key || FormatSpecifiers.compatible(english: key, translation: translated) ? translated : key
    }

    private static func isolated(_ argument: CVarArg) -> CVarArg {
        guard let text = argument as? String else { return argument }
        return BidiText.isolated(text)
    }
}
